#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
MiniCut update patch 5: PROGRESSIVE PROXY, MEDIA CARDS, NODE COLOURS
=====================================================================
Install AFTER apply_perf_gpu_patch_v5.py.

  * Proxy in pieces: a video is turned into a proxy piece every 2 seconds, in order. Pieces that are finished are
    used at once, so the preview gets faster while the proxy is still being made, and playing from the start after
    a reset is fast (piece 0 is ready first).
  * Timeline: the yellow bar under the ruler now grows as pieces are finished. The grey line is the whole clip.
  * Node page: the media list is a row of cards with thumbnails (like the sprite list in Scratch); click a card to
    edit that media's nodes. The node blocks in the left list are coloured by category. The preview and the media
    list are split by a draggable divider.
  * Settings -> Appearance: new "Node editor" colours (canvas, grid, node body, text, wire).
  * Clear proxy cache also works with the new folder layout.

Files replaced as a whole (originals are backed up first):
  minicut/render/media.py, minicut/workspace/timeline.py, minicut/workspace/node_editor.py,
  minicut/shared/dialogs.py, minicut/shared/theme.py

    python apply_perf_gpu_patch_v5.py            install the update
    python apply_perf_gpu_patch_v5.py --check    only show what would change
    python apply_perf_gpu_patch_v5.py --revert   undo the last install
    python apply_perf_gpu_patch_v5.py --force    install even if you edited one of these files yourself
"""
import datetime, hashlib, json, os, py_compile, shutil, subprocess, sys

