                                        '    ("nd_wire",      ("Node editor", "Wire colour", "color", "#9fb3d9", None, None)),\n'
                                        '])\n'
                                        '\n'
                                        '\n'
                                        'UI = {k: v[3] for k, v in THEME_DEFS.items()}\n'
                                        '\n'
                                        '\n'
                                        'def load_theme(d):\n'
                                        '    for k, v in (d or {}).items():\n'
                                        '        if k not in THEME_DEFS: continue\n'
                                        '        kind, dflt, lo, hi = THEME_DEFS[k][2:6]\n'
                                        '        try:\n'
                                        '            if kind == "int": UI[k] = max(lo, min(hi, int(v)))\n'
                                        '            elif kind == "float": UI[k] = max(lo, min(hi, float(v)))\n'
                                        '            elif kind == "bool": UI[k] = bool(v)\n'
                                        '            elif kind == "color" and QColor(v).isValid(): UI[k] = QColor(v).name()\n'
                                        '        except Exception: pass\n'
                                        '\n'
                                        '\n'
                                        'def theme_changes(): return {k: v for k, v in UI.items() if v != THEME_DEFS[k][3]}\n'
                                        '\n'
                                        '\n'
                                        'QSS_COLOR_MAP = {"ui_window": ("#0e0e10", "#070b14"), "ui_panel": ("#1b1b1e",), "ui_button": ("#2a2a2e",),\n'
                                        '                 "ui_input": ("#26262a",), "ui_text": ("#e6e6e6",), "ui_text_dim": ("#9fb3d9", "#8fa6d6"),\n'
                                        '                 "ui_accent": ("#22d3ee", "#00c2d1"), "ui_accent2": ("#2f7bff", "#2f6bff")}\n'
                                        '\n'
                                        '\n'
                                        'def build_qss(base):\n'
                                        '    sub = {}\n'
                                        '    for key, olds in QSS_COLOR_MAP.items():\n'
                                        '        if UI[key].lower() != THEME_DEFS[key][3].lower():\n'
                                        '            for o in olds: sub[o] = UI[key]\n'
                                        '    q = base\n'
                                        '    if sub:\n'
                                        '        pat = re.compile("|".join(re.escape(o) for o in sub), re.I)\n'
                                        '        q = pat.sub(lambda m: sub[m.group(0).lower()], q)\n'
                                        '    d = int(UI["ui_font"]) - 12\n'
                                        '    if d: q = re.sub(r"font-size:\\s*(\\d+)px", lambda m: "font-size:%dpx" % max(6, int(m.group(1)) + d), q)\n'
                                        '    return q\n'
                                        '\n'
                                        '\n'
                                        'QSS_BASE = """\n'
                                        "* { color:#d6e2ff; font-family:'Segoe UI','Noto Sans Thai','Inter',sans-serif; font-size:12px; }\n"
                                        'QFrame#Shell { background:#070b14; border:1px solid #18233d; border-radius:14px; }\n'
                                        'QFrame#Shell[flat="true"] { border:none; border-radius:0px; }\n'
