                                        'QFrame#Panel { background:#0d1424; border:1px solid #17223b; border-radius:12px; }\n'
                                        'QFrame#Hero { background:qlineargradient(x1:0,y1:0,x2:1,y2:1, stop:0 #10224a, stop:1 #0a1226); border:1px solid '
                                        '#1d2f57; border-radius:16px; }\n'
                                        'QFrame#Card { background:#0d1424; border:1px solid #22345c; border-radius:14px; }\n'
                                        'QPushButton { background:#141f36; border:1px solid #22314f; border-radius:8px; padding:6px 14px; }\n'
                                        'QPushButton:hover { background:#1a2948; border-color:#2f7bff; }\n'
                                        'QPushButton:disabled { color:#4a5878; }\n'
                                        'QPushButton#Accent { background:qlineargradient(x1:0,y1:0,x2:1,y2:0, stop:0 #2f6bff, stop:1 #00a8ff); border:none; '
                                        'color:white; font-weight:700; }\n'
                                        'QPushButton#Accent:hover { background:qlineargradient(x1:0,y1:0,x2:1,y2:0, stop:0 #4a80ff, stop:1 #29b8ff); }\n'
                                        'QToolButton { background:transparent; border:none; border-radius:6px; padding:4px 7px; color:#b8c7e8; }\n'
                                        'QToolButton:hover { background:#18264a; }\n'
                                        'QToolButton:checked { background:#16305f; color:#6fb1ff; }\n'
                                        'QToolButton#WinClose:hover { background:#c42b3a; color:white; }\n'
                                        'QToolButton::menu-indicator { image:none; }\n'
                                        'QLineEdit, QSpinBox, QDoubleSpinBox, QComboBox, QPlainTextEdit, QKeySequenceEdit, QFontComboBox {\n'
                                        '  background:#0a1020; border:1px solid #1f2d4a; border-radius:6px; padding:3px 6px; '
                                        'selection-background-color:#2f7bff; }\n'
                                        'QLineEdit:focus, QSpinBox:focus, QDoubleSpinBox:focus, QPlainTextEdit:focus, QComboBox:focus { border-color:#2f7bff; '
                                        '}\n'
                                        'QComboBox::drop-down { border:none; width:18px; }\n'
                                        'QDoubleSpinBox#PropSpin::up-button, QDoubleSpinBox#PropSpin::down-button { subcontrol-origin:border; width:0px; '
                                        'border:none; }\n'
                                        'QComboBox QAbstractItemView { background:#0d1424; border:1px solid #22314f; selection-background-color:#2f7bff; '
                                        'outline:none; }\n'
                                        'QTabWidget::pane { border:none; }\n'
                                        'QTabBar::tab { background:transparent; padding:6px 10px; color:#6b7a99; border-bottom:2px solid transparent; }\n'
                                        'QTabBar::tab:selected { color:#6fb1ff; border-bottom:2px solid #2f7bff; }\n'
